<script setup lang="ts">
import {computed,ref} from 'vue';
import {validStockSymbol,type LivingData,type WidgetContent} from './model.ts';
const props=defineProps<{living?:LivingData;save:(c:WidgetContent)=>Promise<void>}>();
const base=computed(()=>props.living??{symbol:'116.00700',count:0,reminders:[]}),list=computed(()=>base.value.symbols?.length?base.value.symbols:[base.value.symbol]);
const symbol=ref(''),busy=ref(false),error=ref('');
const presets=[{symbol:'116.00700',name:'腾讯控股'},{symbol:'1.000001',name:'上证指数'},{symbol:'0.399001',name:'深证成指'},{symbol:'0.399006',name:'创业板指'}];
const name=(s:string)=>presets.find(p=>p.symbol===s)?.name||s;
async function update(symbols:string[],selected=base.value.symbol){busy.value=true;error.value='';try{await props.save({living:{...base.value,symbols,symbol:selected}});return true;}catch(e){error.value=String(e);return false;}finally{busy.value=false;}}
async function add(value=symbol.value.trim()){if(!validStockSymbol(value)){error.value='请输入有效代码，如 116.00700、1.600519、0.000001';return;}if(list.value.includes(value)){error.value='这只证券已在自选中';return;}if(list.value.length>=8){error.value='最多关注 8 只证券';return;}if(await update([...list.value,value]))symbol.value='';}
function remove(s:string){const rest=list.value.filter(x=>x!==s);if(rest.length)void update(rest,s===base.value.symbol?rest[0]:base.value.symbol);}
</script>
<template><section class="watchlist-editor"><header>自选列表 <small>{{ list.length }} / 8</small></header><label v-for="s in list" :key="s" class="watchlist-row"><input type="radio" name="selected-stock" :checked="base.symbol===s" :disabled="busy" :aria-label="`关注${name(s)}`" @change="update(list,s)"/><span>{{ name(s) }}<small>{{ s }}</small></span><button :disabled="busy||list.length<=1" :aria-label="`移除${name(s)}`" @click="remove(s)">移除</button></label><div class="watchlist-presets"><button v-for="p in presets.filter(p=>!list.includes(p.symbol))" :key="p.symbol" :disabled="busy||list.length>=8" @click="add(p.symbol)">+ {{ p.name }}</button></div><form @submit.prevent="add()"><input v-model="symbol" placeholder="输入证券代码" aria-label="自选证券代码" :disabled="busy"/><button :disabled="busy||list.length>=8">添加</button></form><p>沪市 1.600519 · 深市 0.000001 · 港股 116.00700。点击组件上的“自选”可切换和对比行情。</p><p v-if="error" role="alert">{{ error }}</p></section></template>
<style scoped>.watchlist-editor{display:grid;gap:10px;font-size:13px}.watchlist-editor header{display:flex;justify-content:space-between}.watchlist-editor small,.watchlist-editor p{font-size:11px;color:var(--ui-text-tertiary)}.watchlist-row{display:flex;gap:10px;align-items:center;padding:6px 0;border-bottom:1px solid var(--ui-border)}.watchlist-row>span{flex:1;display:grid;gap:3px}.watchlist-row input{accent-color:#b4987b}.watchlist-editor button{border:1px solid var(--ui-border);border-radius:7px;padding:6px 9px;font:inherit;background:var(--ui-surface-alt);color:inherit;cursor:pointer}.watchlist-editor button:disabled{opacity:.4;cursor:default}.watchlist-presets{display:flex;flex-wrap:wrap;gap:5px}.watchlist-editor form{display:flex;gap:8px}.watchlist-editor form input{flex:1;min-width:0;background:var(--ui-surface);color:inherit;border:1px solid var(--ui-border);border-radius:7px;padding:7px;font:inherit}.watchlist-editor p{line-height:1.7;margin:0}.watchlist-editor p[role=alert]{color:#bd6758}</style>
